#include <deque>
#include <iostream>

void demonstrate_shrinkage() {
    std::deque<int> d(100000, 1);
    std::cout << "Initial size: " << d.size() << std::endl;

    // Remove most elements
    for (int i = 0; i < 99990; ++i) {
        d.pop_back();
    }

    // Deque implementation likely releases blocks, reducing actual memory footprint.
    // A vector would still hold the capacity for 100000 elements.
    std::cout << "Final size: " << d.size() << std::endl;

    d.push_front(0); // O(1) insertion at front
}
